#!/usr/bin/env bash
# Removes everything that is generated by building or running the project
# (or by generating the documentation),
# leaving only the source tree.
#
#   scripts/clean.sh          # build output, database, lock files, node_modules
#   scripts/clean.sh --all    # also the built dashboard (frontend/dist);
#                             # rebuilt by npm run build or scripts/run_all.sh
#
# Stop any running sensor-server / sensor-poller first.
set -euo pipefail
cd "$(dirname "$0")/.."

if pgrep -f 'build/sensor-(server|poller)' >/dev/null 2>&1; then
  echo "sensor-server or sensor-poller is still running; stop it first (Ctrl+C or: pkill -f 'build/sensor-')" >&2
  exit 1
fi

targets=(
  build                         # CMake build tree, binaries, object files
  docs                          # generated Doxygen documentation
  data/sensors.db               # SQLite database (recorded readings, alarms)
  data/sensors.db-wal
  data/sensors.db-shm
  data/sensors.db.sampler.lock  # sampler lock file
  frontend/node_modules         # npm packages (restored by npm ci)
  frontend/.vite
)
if [[ "${1:-}" == "--all" ]]; then
  targets+=(frontend/dist)
fi

for t in "${targets[@]}"; do
  if [[ -e "$t" ]]; then
    rm -rf -- "$t"
    echo "removed $t"
  fi
done

# Simulated hardware trees and test databases in /tmp (from --fake and TESTING.md)
for t in /tmp/fake-sys /tmp/sd-test; do
  [[ -e "$t" ]] && rm -rf -- "$t" && echo "removed $t"
done

# Keep the (now empty) data directory so the default --db path works.
mkdir -p data
echo "clean."
